{
    if (stressGc)
    {
        string s = "";
        for (int i = 0; i < gcConcatIterations; i++) s += i.ToString();
        GC.KeepAlive(s);

        for (int i = 0; i < gcArrayAllocs; i++)
        {
            var block = new object[10000];
            GC.KeepAlive(block);
        }
    }

    if (stressCpu)
    {
        // A busca exaustiva por todos os GameObjects na cena a cada frame foi removida
        // para evitar a varredura linear de alta intensidade sobre a CPU.
    }

    if (stressDraw && testPrefab != null)
    {
        int n = Mathf.Max(1, cubesPerFrame);
        for (int i = 0; i < n; i++) SpawnOne();
    }
}",
      "explicacao_didatica": "O tempo de CPU (processador principal) representa a duração necessária para a máquina calcular a lógica do jogo antes de enviar os dados para a placa de vídeo. Para mantermos 60 quadros por segundo, o orçamento máximo de cada quadro deve ser de 16.7 milissegundos (ms). O método GameObject.FindObjectsOfType percorre e inspeciona todos os objetos presentes na memória da cena; ao ser executado repetidamente dentro do método Update (que roda a cada quadro gerado), essa busca contínua sobrecarrega o processador, gerando o pico de tempo e travamentos visíveis."
    }
  ],
